R,C=28,11
marks=[(0,7),(2,3),(2,7),(2,9),(4,1),(4,2),(5,7),(6,5),(7,5),(11,8),(13,0),(13,8),(14,4),(15,1),(15,4),(15,10),(17,0),(20,3),(20,4),(20,9),(21,5),(21,7),(22,1),(23,3),(23,7),(27,5),(27,9)]
grid=[[1]*C for _ in range(R)]
for r,c in marks:grid[r][c]=7
# fill between extreme markers per row/col
for r in range(R):
 cs=[c for rr,c in marks if rr==r]
 if len(cs)>=2:
  for c in range(min(cs)+1,max(cs)):
   if grid[r][c]==1:grid[r][c]=3
for c in range(C):
 rs=[r for r,cc in marks if cc==c]
 if len(rs)>=2:
  for r in range(min(rs)+1,max(rs)):
   if grid[r][c]==1:grid[r][c]=3
print('\n'.join(' '.join(map(str,row)) for row in grid))
import json
print(json.dumps({'action':'submit','grid':grid}))
